    17→public class BridgeWebSocketServer extends WebSocketServer {
    18→
    19→    private static final Logger log = LoggerFactory.getLogger(BridgeWebSocketServer.class);
    20→    private final Set<WebSocket> clients = Collections.newSetFromMap(new ConcurrentHashMap<>());
    21→
    22→    public BridgeWebSocketServer(int port) {
    23→        super(new InetSocketAddress("localhost", port));
    24→        setReuseAddr(true);
    25→    }
    26→
    27→    @Override
    28→    public void onOpen(WebSocket conn, ClientHandshake handshake) {
    29→        clients.add(conn);
